117	// Apply default configuration to any optional user configuration and handle known errors
118	export async function createNxReleaseConfig(
119	  projectGraph: ProjectGraph,
120	  projectFileMap: ProjectFileMap,
121	  userConfig: NxJsonConfiguration['release'] = {}
122	): Promise<{
123	  error: null | CreateNxReleaseConfigError;
124	  nxReleaseConfig: NxReleaseConfig | null;
125	}> {
126	  if (userConfig.projects && userConfig.groups) {
127	    return {
128	      error: {
129	        code: 'PROJECTS_AND_GROUPS_DEFINED',
130	        data: {},
131	      },
132	      nxReleaseConfig: null,
133	    };
134	  }
135	
136	  if (hasInvalidGitConfig(userConfig)) {
137	    return {
138	      error: {
139	        code: 'GLOBAL_GIT_CONFIG_MIXED_WITH_GRANULAR_GIT_CONFIG',
140	        data: {},
141	      },
142	      nxReleaseConfig: null,
143	    };
144	  }
145	
146	  if (hasInvalidConventionalCommitsConfig(userConfig)) {
147	    return {
148	      error: {
149	        code: 'CONVENTIONAL_COMMITS_SHORTHAND_MIXED_WITH_OVERLAPPING_GENERATOR_OPTIONS',
150	        data: {},
151	      },
152	      nxReleaseConfig: null,
153	    };
154	  }
155	
156	  const gitDefaults = {
157	    commit: false,
158	    commitMessage: 'chore(release): publish {version}',
159	    commitArgs: '',
160	    tag: false,
161	    tagMessage: '',
162	    tagArgs: '',
163	    stageChanges: false,
164	  };
165	  const versionGitDefaults = {
166	    ...gitDefaults,
167	    stageChanges: true,
168	  };
169	  const changelogGitDefaults = {
170	    ...gitDefaults,
171	    commit: true,
172	    tag: true,
173	  };
174	
175	  const defaultFixedReleaseTagPattern = 'v{version}';
176	  /**
177	   * TODO: in v20, make it so that this pattern is used by default when any custom groups are used
178	   */
179	  const defaultFixedGroupReleaseTagPattern = '{releaseGroupName}-v{version}';
180	  const defaultIndependentReleaseTagPattern = '{projectName}@{version}';
181	
182	  const workspaceProjectsRelationship =
183	    userConfig.projectsRelationship || 'fixed';
184	
185	  const defaultGeneratorOptions: {
186	    currentVersionResolver?: string;
187	    specifierSource?: string;
188	  } = {};
189	
190	  if (userConfig.version?.conventionalCommits) {
191	    defaultGeneratorOptions.currentVersionResolver = 'git-tag';
192	    defaultGeneratorOptions.specifierSource = 'conventional-commits';
193	  }
194	  if (userConfig.versionPlans) {
195	    defaultGeneratorOptions.specifierSource = 'version-plans';
196	  }
197	
198	  const userGroups = Object.values(userConfig.groups ?? {});
199	  const disableWorkspaceChangelog =
200	    userGroups.length > 1 ||
201	    (userGroups.length === 1 &&
202	      userGroups[0].projectsRelationship === 'independent') ||
203	    (userConfig.projectsRelationship === 'independent' &&
