unction to analyze files to create dependencies for the {@link ProjectGraph}\n   */\n  createDependencies?: CreateDependencies<TOptions>;\n\n  /**\n   * Provides a function to create metadata for the {@link ProjectGraph}\n   */\n  createMetadata?: CreateMetadata<TOptions>;\n};\n\n/**\n * A plugin for Nx\n */\nexport type NxPlugin = NxPluginV2;\n","resolvedModuleNames":["/workspace/repo/packages/nx/src/config/project-graph.ts","/workspace/repo/packages/nx/src/config/workspace-json-project-json.ts","/workspace/repo/packages/nx/src/config/nx-json.ts","/workspace/repo/packages/nx/src/project-graph/project-graph-builder.ts","/workspace/repo/packages/nx/release/changelog-renderer/index.ts","/workspace/repo/packages/nx/src/utils/fileutils.ts","/workspace/repo/packages/nx/src/utils/package-manager.ts","/workspace/repo/packages/nx/src/utils/workspace-root.ts","/workspace/repo/packages/nx/src/project-graph/plugins/index.ts","/workspace/repo/packages/nx/src/project-graph/build-project-graph.ts"]}],["/workspace/repo/packages/nx/src/project-graph/plugins/loader.ts",{"fileContent":"// This file contains methods and utilities that should **only** be used by the plugin worker.\n\nimport { ProjectConfiguration } from '../../config/workspace-json-project-json';\n\nimport { join } from 'node:path/posix';\nimport { getNxRequirePaths } from '../../utils/installation-directory';\nimport {\n  PackageJson,\n  readModulePackageJsonWithoutFallbacks,\n} from '../../utils/package-json';\nimport { readJsonFile } from '../../utils/fileutils';\nimport { workspaceRoot } from '../../utils/workspace-root';\nimport { existsSync } from 'node:fs';\nimport {\n  registerTranspiler,\n  registerTsConfigPaths,\n} from '../../plugins/js/utils/register';\nimport {\n  ProjectRootMappings,\n  findProjectForPath,\n} from '../utils/find-project-for-path';\nimport { normalizePath } from '../../utils/path';\nimport { logger } from '../../utils/logger';\n\nimport type * as ts from 'typescript';\nimport { extname } from 'node:path';\nimport type { PluginConfiguration } from '../../config/nx-json';\nimport { retrieveProjectConfigurationsWithoutPluginInference } from '../utils/retrieve-workspace-files';\nimport { LoadedNxPlugin } from './internal-api';\nimport { LoadPluginError } from '../error-types';\nimport path = require('node:path/posix');\nimport { readTsConfig } from '../../plugins/js/utils/typescript';\nimport { loadResolvedNxPluginAsync } from './load-resolved-plugin';\n\nexport function readPluginPackageJson(\n  pluginName: string,\n  projects: Record<string, ProjectConfiguration>,\n  paths = getNxRequirePaths()\n): {\n  path: string;\n  json: PackageJson;\n} {\n  try {\n    const result = readModulePackageJsonWithoutFallbacks(pluginName, paths);\n    return {\n      json: result.packageJson,\n      path: result.path,\n    };\n  } catch (e) {\n    if (e.code === 'MODULE_NOT_FOUND') {\n      const localPluginPath = resolveLocalNxPlugin(pluginName, projects);\n      if (localPluginPath) {\n        const localPluginPackageJson = path.join(\n          localPluginPath.path,\n          'package.json'\n        );\n        if (!unregisterPluginTSTranspiler) {\n          registerPluginTSTranspiler();\n        }\n        return {\n          path: localPluginPackageJson,\n          json: readJsonFile(localPluginPackageJson),\n        };\n      }\n    }\n    throw e;\n  }\n}\n\nexport function resolveLocalNxPlugin(\n  importPath: string,\n  projects: Record<string, ProjectConfiguration>,\n  root = workspaceRoot\n): { path: string; projectConfig: ProjectConfiguration } | null {\n  return lookupLocalPlugin(importPath, projects, root);\n}\n\nexport let unregisterPluginTSTranspiler: (() => void) | null = null;\n\n/**\n * Register swc-node or ts-node if they are not currently registered\n * with some default settings which work well for Nx plugins.\n */\nexport function registerPluginTSTranspiler() {\n  // Get the first tsconfig that matches the allowed set\n  const tsConfigName = [\n    join(workspaceRoot, 'tsconfig.base.json'),\n    join(workspaceRoot, 'tsconfig.json'),\n  ].find((x) => existsSync(x));\n\n  if (!tsConfigName) {\n    return;\n  }\n\n  const tsConfig: Partial<ts.ParsedCommandLine> = tsConfigName\n    ? readTsConfig(tsConfigName)\n    : {};\n  const cleanupFns = [\n    registerTsConfigPaths(tsConfigName),\n    registerTranspiler(\n      {\n        experimentalDecorators: true,\n        emitDecoratorMetadata: true,\n        ...tsConfig.options,\n      },\n      tsConfig.raw\n    ),\n  ];\n  unregisterPluginTSTranspiler = () => {\n    cleanupFns.forEach((fn) => fn?.());\n  };\n}\n\nfunction lookupLocalPlugin(\n  importPath: string,\n  projects: Record<string, ProjectConfiguration>,\n  root = workspaceRoot\n) {\n  const projectConfig = findNxProjectForImportPath(importPath, projects, root);\n  if (!projectConfig) {\n    return null;\n  }\n\n  return { path: path.join(root, projectConfig.root), projectConfig };\n}\n\nfunction findNxProjectForImportPath(\n  importPath: string,\n  projects: Record<string, ProjectConfiguration>,\n  root = workspaceRoot\n): ProjectConfiguration | null {\n  const tsConfigPaths: Record<string, string[]> = readTsConfigPaths(root);\n  const possiblePaths = tsConfigPaths[importPath]?.map((p) =>\n    normalizePath(path.relative(root, path.join(root, p)))\n  );\n  if (possiblePaths?.length) {\n    const projectRootMappings: ProjectRootMappings = new Map();\n    const projectNameMap = new Map<string, ProjectConfiguration>();\n    for (const projectRoot in projects) {\n      const project = projects[projectRoot];\n      projectRootMappings.set(project.root, project.name);\n      projectNameMap.set(project.name, project);\n    }\n    for (const tsConfigPath of possiblePaths) {\n      const nxProject = findProjectForPath(tsConfigPath, projectRootMappings);\n      if (nxProject) {\n        return projectNameMap.get(nxProject);\n      }\n    }\n    logger.verbose(\n      'Unable to find local plugin',\n      possiblePaths,\n      projectRootMappings\n    );\n    throw new Error(\n      'Unable to resolve local plugin with import path ' + importPath\n    );\n  }\n}\n\nlet tsconfigPaths: Record<string, string[]>;\n\nfunction readTsConfigPaths(root: string = workspaceRoot) {\n  if (!tsconfigPaths) {\n    const tsconfigPath: string | null = ['tsconfig.base.json', 'tsconfig.json']\n      .map((x) => path.join(root, x))\n      .filter((x) => existsSync(x))[0];\n    if (!tsconfigPath) {\n      throw new Error('unable to find tsconfig.base.json or tsconfig.json');\n    }\n    const { compilerOptions } = readJsonFile(tsconfigPath);\n    tsconfigPaths = compilerOptions?.paths;\n  }\n  return tsconfigPaths ?? {};\n}\n\nfunction readPluginMainFromProjectConfiguration(\n  plugin: ProjectConfiguration\n): string | null {\n  const { main } =\n    Object.values(plugin.targets).find((x) =>\n      [\n        '@nx/js:tsc',\n        '@nrwl/js:tsc',\n        '@nx/js:swc',\n        '@nrwl/js:swc',\n        '@nx/node:package',\n        '@nrwl/node:package',\n      ].includes(x.executor)\n    )?.options ||\n    plugin.targets?.build?.options ||\n    {};\n  return main;\n}\n\nexport function getPluginPathAndName(\n  moduleName: string,\n  paths: string[],\n  projects: Record<string, ProjectConfiguration>,\n  root: string\n) {\n  let pluginPath: string;\n  let shouldRegisterTSTranspiler = false;\n  try {\n    pluginPath = require.resolve(moduleName, {\n      paths,\n    });\n    const extension = path.extname(pluginPath);\n    shouldRegisterTSTranspiler = extension === '.ts';\n  } catch (e) {\n    if (e.code === 'MODULE_NOT_FOUND') {\n      const plugin = resolveLocalNxPlugin(moduleName, projects, root);\n      if (plugin) {\n        shouldRegisterTSTranspiler = true;\n        const main = readPluginMainFromProjectConfiguration(\n          plugin.projectConfig\n        );\n        pluginPath = main ? path.join(root, main) : plugin.path;\n      } else {\n        logger.error(`Plugin listed in \\`nx.json\\` not found: ${moduleName}`);\n        throw e;\n      }\n    } else {\n      throw e;\n    }\n  }\n  const packageJsonPath = path.join(pluginPath, 'package.json');\n\n  const { name } =\n    !['.ts', '.js'].some((x) => extname(moduleName) === x) && // Not trying to point to a ts or js file\n    existsSync(packageJsonPath) // plugin has a package.json\n      ? readJsonFile(packageJsonPath) // read name from package.json\n      : { name: moduleName };\n  return { pluginPath, name, shouldRegisterTSTranspiler };\n}\n\nlet projectsWithoutInference: Record<string, ProjectConfiguration>;\n\nexport function loadNxPlugin(plugin: PluginConfiguration, root: string) {\n  return [\n    loadNxPluginAsync(plugin, getNxRequirePaths(root), root),\n    () => {},\n  ] as const;\n}\n\nexport async function resolveNxPlugin(\n  moduleName: string,\n  root: string,\n  paths: string[]\n) {\n  try {\n    require.resolve(moduleName);\n  } catch {\n    // If a plugin cannot be resolved, we will need projects to resolve it\n    projectsWithoutInference ??=\n      await retrieveProjectConfigurationsWithoutPluginInference(root);\n  }\n  const { pluginPath, name, shouldRegisterTSTranspiler } = getPluginPathAndName(\n    moduleName,\n    paths,\n    projectsWithoutInference,\n    root\n  );\n  return { pluginPath, name, shouldRegisterTSTranspiler };\n}\n\nexport async function loadNxPluginAsync(\n  pluginConfiguration: PluginConfiguration,\n  paths: string[],\n  root: string\n): Promise<LoadedNxPlugin> {\n  const moduleName =\n    typeof pluginConfiguration === 'string'\n      ? pluginConfiguration\n      : pluginConfiguration.plugin;\n  try {\n    const { pluginPath, name, shouldRegisterTSTranspiler } =\n      await resolveNxPlugin(moduleName, root, paths);\n\n    if (shouldRegisterTSTranspiler) {\n      registerPluginTSTranspiler();\n    }\n    return loadResolvedNxPluginAsync(pluginConfiguration, pluginPath, name);\n  } catch (e) {\n    throw new LoadPluginError(moduleName, e);\n  }\n}\n","resolvedModuleNames":["/workspace/repo/packages/nx/src/config/workspace-json-project-json.ts","/workspace/repo/packages/nx/src/utils/installation-directory.ts","/workspace/repo/packages/nx/src/utils/package-json.ts","/workspace/repo/packages/nx/src/utils/fileutils.ts","/workspace/repo/packages/nx/src/utils/workspace-root.ts","/workspace/repo/packages/nx/src/plugins/js/utils/register.ts","/workspace/repo/packages/nx/src/project-graph/utils/find-project-for-path.ts","/workspace/repo/packages/nx/src/utils/path.ts","/workspace/repo/packages/nx/src/utils/logger.ts","/workspace/repo/packages/nx/src/config/nx-json.ts","/workspace/repo/packages/nx/src/project-graph/utils/retrieve-workspace-files.ts","/workspace/repo/packages/nx/src/project-graph/plugins/internal-api.ts","/workspace/repo/packages/nx/src/project-graph/error-types.ts","/workspace/repo/packages/nx/src/plugins/js/utils/typescript.ts","/workspace/repo/packages/nx/src/project-graph/plugins/load-resolved-plugin.ts","/workspace/repo/packages/nx/src/project-graph/utils/project-configuration-utils.ts","/workspace/repo/packages/nx/src/utils/package-manager.ts","/workspace/repo/packages/nx/src/utils/json.ts","/workspace/repo/packages/nx/src/utils/json.ts","/workspace/repo/packages/nx/src/config/project-graph.ts","/workspace/repo/packages/nx/release/changelog-renderer/index.ts","/workspace/repo/packages/nx/src/adapter/angular-json.ts","/workspace/repo/packages/nx/src/utils/workspace-context.ts","/workspace/repo/packages/nx/src/project-graph/utils/build-all-workspace-files.ts","/workspace/repo/packages/nx/src/project-graph/plugins/get-plugins.ts","/workspace/repo/packages/nx/src/project-graph/plugins/public-api.ts","/workspace/repo/packages/nx/src/project-graph/plugins/isolation/index.ts","/workspace/repo/packages/nx/src/project-graph/plugins/loader.ts","/workspace/repo/packages/nx/src/project-graph/plugins/utils.ts","/workspace/repo/packages/nx/src/native/index.d.ts"]}],["/workspace/repo/packages/nx/src/utils/installation-directory.ts",{"fileContent":"import { join } from 'path';\nimport { workspaceRoot } from './workspace-root';\n\nexport function getNxInstallationPath(root: string = workspaceRoot) {\n  return join(root, '.nx', 'installation');\n}\n\nexport function getNxRequirePaths(root: string = workspaceRoot) {\n  return [root, getNxInstallationPath(root)];\n}\n","resolvedModuleNames":["/workspace/repo/packages/nx/src/utils/workspace-root.ts","/workspace/repo/packages/nx/src/utils/fileutils.ts"]}],["/workspace/repo/packages/nx/src/utils/package-json.ts",{"fileContent":"import { existsSync } from 'fs';\nimport { dirname, join } from 'path';\nimport { NxJsonConfiguration } from '../config/nx-json';\nimport {\n  ProjectConfiguration,\n  ProjectMetadata,\n  TargetConfiguration,\n} from '../config/workspace-json-project-json';\nimport { mergeTargetConfigurations } from '../project-graph/utils/project-configuration-utils';\nimport { readJsonFile } from './fileutils';\nimport { getNxRequirePaths } from './installation-directory';\nimport {\n  PackageManagerCommands,\n  getPackageManagerCommand,\n} from './package-manager';\n\nexport interface NxProjectPackageJsonConfiguration\n  extends Partial<ProjectConfiguration> {\n  includedScripts?: string[];\n}\n\nexport type ArrayPackageGroup = { package: string; version: string }[];\nexport type MixedPackageGroup =\n  | (string | { package: string; version: string })[]\n  | Record<string, string>;\nexport type PackageGroup = MixedPackageGroup | ArrayPackageGroup;\n\nexport interface NxMigrationsConfiguration {\n  migrations?: string;\n  packageGroup?: PackageGroup;\n}\n\ntype PackageOverride = { [key: string]: string | PackageOverride };\n\nexport interface PackageJson {\n  // Generic Package.Json Configuration\n  name: string;\n  version: string;\n  license?: string;\n  private?: boolean;\n  scripts?: Record<string, string>;\n  type?: 'module' | 'commonjs';\n  main?: string;\n  types?: string;\n  // interchangeable with `types`: https://www.typescriptlang.org/docs/handbook/declaration-files/publishing.html#including-declarations-in-your-npm-package\n  typings?: string;\n  module?: string;\n  exports?:\n    | string\n    | Record<\n        string,\n        string | { types?: string; require?: string; import?: string }\n      >;\n  dependencies?: Record<string, string>;\n  devDependencies?: Record<string, string>;\n  optionalDependencies?: Record<string, string>;\n  peerDependencies?: Record<string, string>;\n  peerDependenciesMeta?: Record<string, { optional: boolean }>;\n  resolutions?: Record<string, string>;\n  pnpm?: {\n    overrides?: PackageOverride;\n  };\n  overrides?: PackageOverride;\n  bin?: Record<string, string> | string;\n  workspaces?:\n    | string[]\n    | {\n        packages: string[];\n      };\n  publishConfig?: Record<string, string>;\n  files?: string[];\n\n  // Nx Project Configuration\n  nx?: NxProjectPackageJsonConfiguration;\n\n  // Nx Plugin Configuration\n  generators?: string;\n  schematics?: string;\n  builders?: string;\n  executors?: string;\n  'nx-migrations'?: string | NxMigrationsConfiguration;\n  'ng-update'?: string | NxMigrationsConfiguration;\n  packageManager?: string;\n  description?: string;\n  keywords?: string[];\n}\n\nexport function normalizePackageGroup(\n  packageGroup: PackageGroup\n): ArrayPackageGroup {\n  return Array.isArray(packageGroup)\n    ? packageGroup.map((x) =>\n        typeof x === 'string' ? { package: x, version: '*' } : x\n      )\n    : Object.entries(packageGroup).map(([pkg, version]) => ({\n        package: pkg,\n        version,\n      }));\n}\n\nexport function readNxMigrateConfig(\n  json: Partial<PackageJson>\n): NxMigrationsConfiguration & { packageGroup?: ArrayPackageGroup } {\n  const parseNxMigrationsConfig = (\n    fromJson?: string | NxMigrationsConfiguration\n  ): NxMigrationsConfiguration & { packageGroup?: ArrayPackageGroup } => {\n    if (!fromJson) {\n      return {};\n    }\n    if (typeof fromJson === 'string') {\n      return { migrations: fromJson, packageGroup: [] };\n    }\n\n    return {\n      ...(fromJson.migrations ? { migrations: fromJson.migrations } : {}),\n      ...(fromJson.packageGroup\n        ? { packageGroup: normalizePackageGroup(fromJson.packageGroup) }\n        : {}),\n    };\n  };\n\n  return {\n    ...parseNxMigrationsConfig(json['ng-update']),\n    ...parseNxMigrationsConfig(json['nx-migrations']),\n    // In case there's a `migrations` field in `package.json`\n    ...parseNxMigrationsConfig(json as any),\n  };\n}\n\nexport function buildTargetFromScript(\n  script: string,\n  scripts: Record<string, string> = {},\n  packageManagerCommand: PackageManagerCommands\n): TargetConfiguration {\n  return {\n    executor: 'nx:run-script',\n    options: {\n      script,\n    },\n    metadata: {\n      scriptContent: scripts[script],\n      runCommand: packageManagerCommand.run(script),\n    },\n  };\n}\n\nlet packageManagerCommand: PackageManagerCommands | undefined;\n\nexport function getMetadataFromPackageJson(\n  packageJson: PackageJson\n): ProjectMetadata {\n  const { scripts, nx, description } = packageJson ?? {};\n  const includedScripts = nx?.includedScripts || Object.keys(scripts ?? {});\n  return {\n    targetGroups: {\n      ...(includedScripts.length ? { 'NPM Scripts': includedScripts } : {}),\n    },\n    description,\n  };\n}\n\nexport function getTagsFromPackageJson(packageJson: PackageJson): string[] {\n  const tags = packageJson.private ? ['npm:private'] : ['npm:public'];\n  if (packageJson.keywords?.length) {\n    tags.push(...packageJson.keywords.map((k) => `npm:${k}`));\n  }\n  if (packageJson?.nx?.tags?.length) {\n    tags.push(...packageJson?.nx.tags);\n  }\n  return tags;\n}\n\nexport function readTargetsFromPackageJson(\n  packageJson: PackageJson,\n  nxJson: NxJsonConfiguration\n) {\n  const { scripts, nx, private: isPrivate } = packageJson ?? {};\n  const res: Record<string, TargetConfiguration> = {};\n  const includedScripts = nx?.includedScripts || Object.keys(scripts ?? {});\n  for (const script of includedScripts) {\n    packageManagerCommand ??= getPackageManagerCommand();\n    res[script] = buildTargetFromScript(script, scripts, packageManagerCommand);\n  }\n  for (const targetName in nx?.targets) {\n    res[targetName] = mergeTargetConfigurations(\n      nx?.targets[targetName],\n      res[targetName]\n    );\n  }\n\n  /**\n   * Add implicit nx-release-publish target for all package.json files that are\n   * not marked as `\"private\": true` to allow for lightweight configuration for\n   * package based repos.\n   *\n   * Any targetDefaults for the nx-release-publish target set by the user should\n   * be merged with the implicit target.\n   */\n  if (!isPrivate && !res['nx-release-publish']) {\n    const nxReleasePublishTargetDefaults =\n      nxJson?.targetDefaults?.['nx-release-publish'] ?? {};\n    res['nx-release-publish'] = {\n      executor: '@nx/js:release-publish',\n      ...nxReleasePublishTargetDefaults,\n      dependsOn: [\n        // For maximum correctness, projects should only ever be published once their dependencies are successfully published\n        '^nx-release-publish',\n        ...(nxReleasePublishTargetDefaults.dependsOn ?? []),\n      ],\n      options: {\n        ...(nxReleasePublishTargetDefaults.options ?? {}),\n      },\n    };\n  }\n\n  return res;\n}\n\n/**\n * Uses `require.resolve` to read the package.json for a module.\n *\n * This will fail if the module doesn't export package.json\n *\n * @returns package json contents and path\n */\nexport function readModulePackageJsonWithoutFallbacks(\n  moduleSpecifier: string,\n  requirePaths = getNxRequirePaths()\n): {\n  packageJson: PackageJson;\n  path: string;\n} {\n  const packageJsonPath: string = require.resolve(\n    `${moduleSpecifier}/package.json`,\n    {\n      paths: requirePaths,\n    }\n  );\n  const packageJson: PackageJson = readJsonFile(packageJsonPath);\n\n  return {\n    path: packageJsonPath,\n    packageJson,\n  };\n}\n\n/**\n * Reads the package.json file for a specified module.\n *\n * Includes a fallback that accounts for modules that don't export package.json\n *\n * @param {string} moduleSpecifier The module to look up\n * @param {string[]} requirePaths List of paths look in. Pass `module.paths` to ensure non-hoisted dependencies are found.\n *\n * @example\n * // Use the caller's lookup paths for non-hoisted dependencies\n * readModulePackageJson('http-server', module.paths);\n *\n * @returns package json contents and path\n */\nexport function readModulePackageJson(\n  moduleSpecifier: string,\n  requirePaths = getNxRequirePaths()\n): {\n  packageJson: PackageJson;\n  path: string;\n} {\n  let packageJsonPath: string;\n  let packageJson: PackageJson;\n\n  try {\n    ({ path: packageJsonPath, packageJson } =\n      readModulePackageJsonWithoutFallbacks(moduleSpecifier, requirePaths));\n  } catch {\n    const entryPoint = require.resolve(moduleSpecifier, {\n      paths: requirePaths,\n    });\n\n    let moduleRootPath = dirname(entryPoint);\n    packageJsonPath = join(moduleRootPath, 'package.json');\n\n    while (!existsSync(packageJsonPath)) {\n      moduleRootPath = dirname(moduleRootPath);\n      packageJsonPath = join(moduleRootPath, 'package.json');\n    }\n\n    packageJson = readJsonFile(packageJsonPath);\n    if (packageJson.name && packageJson.name !== moduleSpecifier) {\n      throw new Error(\n        `Found module ${packageJson.name} while trying to locate ${moduleSpecifier}/package.json`\n      );\n    }\n  }\n\n  return {\n    packageJson,\n    path: packageJsonPath,\n  };\n}\n","resolvedModuleNames":["/workspace/repo/packages/nx/src/config/nx-json.ts","/workspace/repo/packages/nx/src/config/workspace-json-project-json.ts","/workspace/repo/packages/nx/src/project-graph/utils/project-configuration-utils.ts","/workspace/repo/packages/nx/src/utils/fileutils.ts","/workspace/repo/packages/nx/src/utils/installation-directory.ts","/workspace/repo/packages/nx/src/utils/package-manager.ts","/workspace/repo/packages/nx/release/changelog-renderer/index.ts","/workspace/repo/packages/nx/src/utils/workspace-root.ts","/workspace/repo/packages/nx/src/config/project-graph.ts","/workspace/repo/packages/nx/src/utils/logger.ts","/workspace/repo/packages/nx/src/project-graph/plugins/internal-api.ts","/workspace/repo/packages/nx/src/project-graph/error-types.ts","/workspace/repo/packages/nx/src/project-graph/plugins/public-api.ts","/workspace/repo/packages/nx/src/utils/globs.ts","/workspace/repo/packages/nx/src/utils/json.ts","/workspace/repo/packages/nx/src/utils/json.ts","/workspace/repo/packages/nx/src/config/configuration.ts","/workspace/repo/packages/nx/src/project-graph/file-utils.ts","/workspace/repo/packages/nx/src/utils/package-json.ts"]}],["/workspace/repo/packages/nx/src/project-graph/utils/project-configuration-utils.ts",{"fileContent":"import { NxJsonConfiguration, TargetDefaults } from '../../config/nx-json';\nimport { ProjectGraphExternalNode } from '../../config/project-graph';\nimport {\n  ProjectConfiguration,\n  ProjectMetadata,\n  TargetConfiguration,\n  TargetMetadata,\n} from '../../config/workspace-json-project-json';\nimport { NX_PREFIX } from '../../utils/logger';\nimport { readJsonFile } from '../../utils/fileutils';\nimport { workspaceRoot } from '../../utils/workspace-root';\n\nimport { minimatch } from 'minimatch';\nimport { join } from 'path';\nimport { performance } from 'perf_hooks';\nimport { LoadedNxPlugin } from '../plugins/internal-api';\nimport {\n  MergeNodesError,\n  ProjectConfigurationsError,\n  ProjectsWithNoNameError,\n  MultipleProjectsWithSameNameError,\n  isMultipleProjectsWithSameNameError,\n  isProjectsWithNoNameError,\n  ProjectWithNoNameError,\n  ProjectWithExistingNameError,\n  isProjectWithExistingNameError,\n  isProjectWithNoNameError,\n  isAggregateCreateNodesError,\n  AggregateCreateNodesError,\n} from '../error-types';\nimport { CreateNodesResult } from '../plugins/public-api';\nimport { isGlobPattern } from '../../utils/globs';\n\nexport type SourceInformation = [file: string | null, plugin: string];\nexport type ConfigurationSourceMaps = Record<\n  string,\n  Record<string, SourceInformation>\n>;\n\nexport function mergeProjectConfigurationIntoRootMap(\n  projectRootMap: Record<string, ProjectConfiguration>,\n  project: ProjectConfiguration,\n  configurationSourceMaps?: ConfigurationSourceMaps,\n  sourceInformation?: SourceInformation,\n  // This function is used when reading project configuration\n  // in generators, where we don't want to do this.\n  skipTargetNormalization?: boolean\n): void {\n  if (configurationSourceMaps && !configurationSourceMaps[project.root]) {\n    configurationSourceMaps[project.root] = {};\n  }\n  const sourceMap = configurationSourceMaps?.[project.root];\n\n  let matchingProject = projectRootMap[project.root];\n\n  if (!matchingProject) {\n    projectRootMap[project.root] = {\n      root: project.root,\n    };\n    matchingProject = projectRootMap[project.root];\n    if (sourceMap) {\n      sourceMap[`root`] = sourceInformation;\n    }\n  }\n\n  // This handles top level properties that are overwritten.\n  // e.g. `srcRoot`, `projectType`, or other fields that shouldn't be extended\n  // Note: `name` is set specifically here to keep it from changing. The name is\n  // always determined by the first inference plugin to ID a project, unless it has\n  // a project.json in which case it was already updated above.\n  const updatedProjectConfiguration = {\n    ...matchingProject,\n  };\n\n  for (const k in project) {\n    if (\n      ![\n        'tags',\n        'implicitDependencies',\n        'generators',\n        'targets',\n        'metadata',\n        'namedInputs',\n      ].includes(k)\n    ) {\n      updatedProjectConfiguration[k] = project[k];\n      if (sourceMap) {\n        sourceMap[`${k}`] = sourceInformation;\n      }\n    }\n  }\n\n  // The next blocks handle properties that should be themselves merged (e.g. targets, tags, and implicit dependencies)\n  if (project.tags) {\n    updatedProjectConfiguration.tags = Array.from(\n      new Set((matchingProject.tags ?? []).concat(project.tags))\n    );\n\n    if (sourceMap) {\n      sourceMap['tags'] ??= sourceInformation;\n      project.tags.forEach((tag) => {\n        sourceMap[`tags.${tag}`] = sourceInformation;\n      });\n    }\n  }\n\n  if (project.implicitDependencies) {\n    updatedProjectConfiguration.implicitDependencies = (\n      matchingProject.implicitDependencies ?? []\n    ).concat(project.implicitDependencies);\n\n    if (sourceMap) {\n      sourceMap['implicitDependencies'] ??= sourceInformation;\n      project.implicitDependencies.forEach((implicitDependency) => {\n        sourceMap[`implicitDependencies.${implicitDependency}`] =\n          sourceInformation;\n      });\n    }\n  }\n\n  if (project.generators) {\n    // Start with generators config in new project.\n    updatedProjectConfiguration.generators = { ...project.generators };\n\n    if (sourceMap) {\n      sourceMap['generators'] ??= sourceInformation;\n      for (const generator in project.generators) {\n        sourceMap[`generators.${generator}`] = sourceInformation;\n        for (const property in project.generators[generator]) {\n          sourceMap[`generators.${generator}.${property}`] = sourceInformation;\n        }\n      }\n    }\n\n    if (matchingProject.generators) {\n      // For each generator that was already defined, shallow merge the options.\n      // Project contains the new info, so it has higher priority.\n      for (const generator in matchingProject.generators) {\n        updatedProjectConfiguration.generators[generator] = {\n          ...matchingProject.generators[generator],\n          ...project.generators[generator],\n        };\n      }\n    }\n  }\n\n  if (project.namedInputs) {\n    updatedProjectConfiguration.namedInputs = {\n      ...matchingProject.namedInputs,\n      ...project.namedInputs,\n    };\n\n    if (sourceMap) {\n      sourceMap['namedInputs'] ??= sourceInformation;\n      for (const namedInput in project.namedInputs) {\n        sourceMap[`namedInputs.${namedInput}`] = sourceInformation;\n      }\n    }\n  }\n\n  if (project.metadata) {\n    updatedProjectConfiguration.metadata = mergeMetadata(\n      sourceMap,\n      sourceInformation,\n      'metadata',\n      project.metadata,\n      matchingProject.metadata\n    );\n  }\n\n  if (project.targets) {\n    // We merge the targets with special handling, so clear this back to the\n    // targets as defined originally before merging.\n    updatedProjectConfiguration.targets = matchingProject?.targets ?? {};\n    if (sourceMap) {\n      sourceMap['targets'] ??= sourceInformation;\n    }\n\n    // For each target defined in the new config\n    for (const targetName in project.targets) {\n      // Always set source map info for the target, but don't overwrite info already there\n      // if augmenting an existing target.\n\n      const target = project.targets?.[targetName];\n\n      if (sourceMap) {\n        sourceMap[`targets.${targetName}`] = sourceInformation;\n      }\n\n      const normalizedTarget = skipTargetNormalization\n        ? target\n        : resolveCommandSyntacticSugar(target, project.root);\n\n      const mergedTarget = mergeTargetConfigurations(\n        normalizedTarget,\n        matchingProject.targets?.[targetName],\n        sourceMap,\n        sourceInformation,\n        `targets.${targetName}`\n      );\n\n      updatedProjectConfiguration.targets[targetName] = mergedTarget;\n    }\n  }\n\n  projectRootMap[updatedProjectConfiguration.root] =\n    updatedProjectConfiguration;\n}\n\nexport function mergeMetadata<T = ProjectMetadata | TargetMetadata>(\n  sourceMap: Record<string, [file: string, plugin: string]>,\n  sourceInformation: [file: string, plugin: string],\n  baseSourceMapPath: string,\n  metadata: T,\n  matchingMetadata?: T\n): T {\n  const result: T = {\n    ...(matchingMetadata ?? ({} as T)),\n  };\n  for (const [metadataKey, value] of Object.entries(metadata)) {\n    const existingValue = matchingMetadata?.[metadataKey];\n\n    if (Array.isArray(value) && Array.isArray(existingValue)) {\n      for (const item of [...value]) {\n        const newLength = result[metadataKey].push(item);\n        if (sourceMap) {\n          sourceMap[`${baseSourceMapPath}.${metadataKey}.${newLength - 1}`] =\n            sourceInformation;\n        }\n      }\n    } else if (Array.isArray(value) && existingValue === undefined) {\n      result[metadataKey] ??= value;\n      if (sourceMap) {\n        sourceMap[`${baseSourceMapPath}.${metadataKey}`] = sourceInformation;\n      }\n      for (let i = 0; i < value.length; i++) {\n        if (sourceMap) {\n          sourceMap[`${baseSourceMapPath}.${metadataKey}.${i}`] =\n            sourceInformation;\n        }\n      }\n    } else if (typeof value === 'object' && typeof existingValue === 'object') {\n      for (const key in value) {\n        const existingValue = matchingMetadata?.[metadataKey]?.[key];\n\n        if (Array.isArray(value[key]) && Array.isArray(existingValue)) {\n          for (const item of value[key]) {\n            const i = result[metadataKey][key].push(item);\n            if (sourceMap) {\n              sourceMap[`${baseSourceMapPath}.${metadataKey}.${key}.${i - 1}`] =\n                sourceInformation;\n            }\n          }\n        } else {\n          result[metadataKey][key] = value[key];\n          if (sourceMap) {\n            sourceMap[`${baseSourceMapPath}.${metadataKey}`] =\n              sourceInformation;\n          }\n        }\n      }\n    } else {\n      result[metadataKey] = value;\n      if (sourceMap) {\n        sourceMap[`${baseSourceMapPath}.${metadataKey}`] = sourceInformation;\n\n        if (typeof value === 'object') {\n          for (const k in value) {\n            sourceMap[`${baseSourceMapPath}.${metadataKey}.${k}`] =\n              sourceInformation;\n            if (Array.isArray(value[k])) {\n              for (let i = 0; i < value[k].length; i++) {\n                sourceMap[`${baseSourceMapPath}.${metadataKey}.${k}.${i}`] =\n                  sourceInformation;\n              }\n            }\n          }\n        }\n      }\n    }\n  }\n  return result;\n}\n\nexport type ConfigurationResult = {\n  /**\n   * A map of project configurations, keyed by project root.\n   */\n  projects: {\n    [projectRoot: string]: ProjectConfiguration;\n  };\n\n  /**\n   * Node Name -> Node info\n   */\n  externalNodes: Record<string, ProjectGraphExternalNode>;\n\n  /**\n   * Project Root -> Project Name\n   */\n  projectRootMap: Record<string, string>;\n\n  sourceMaps: ConfigurationSourceMaps;\n\n  /**\n   * The list of files that were used to create project configurations\n   */\n  matchingProjectFiles: string[];\n};\n\n/**\n * Transforms a list of project paths into a map of project configurations.\n *\n * @param root The workspace root\n * @param nxJson The NxJson configuration\n * @param workspaceFiles A list of non-ignored workspace files\n * @param plugins The plugins that should be used to infer project configuration\n */\nexport async function createProjectConfigurations(\n  root: string = workspaceRoot,\n  nxJson: NxJsonConfiguration,\n  projectFiles: string[], // making this parameter allows devkit to pick up newly created projects\n  plugins: LoadedNxPlugin[]\n): Promise<ConfigurationResult> {\n  performance.mark('build-project-configs:start');\n\n  const results: Array<ReturnType<LoadedNxPlugin['createNodes'][1]>> = [];\n  const errors: Array<\n    | AggregateCreateNodesError\n    | MergeNodesError\n    | ProjectsWithNoNameError\n    | MultipleProjectsWithSameNameError\n  > = [];\n\n  // We iterate over plugins first - this ensures that plugins specified first take precedence.\n  for (const {\n    createNodes: createNodesTuple,\n    include,\n    exclude,\n    name: pluginName,\n  } of plugins) {\n    const [pattern, createNodes] = createNodesTuple ?? [];\n\n    if (!pattern) {\n      continue;\n    }\n\n    const matchingConfigFiles: string[] = findMatchingConfigFiles(\n      projectFiles,\n      pattern,\n      include,\n      exclude\n    );\n\n    let r = createNodes(matchingConfigFiles, {\n      nxJsonConfiguration: nxJson,\n      workspaceRoot: root,\n    }).catch((e: Error) => {\n      const errorBodyLines = [\n        `An error occurred while processing files for the ${pluginName} plugin.`,\n      ];\n      const error: AggregateCreateNodesError = isAggregateCreateNodesError(e)\n        ? // This is an expected error if something goes wrong while processing files.\n          e\n        : // This represents a single plugin erroring out with a hard error.\n          new AggregateCreateNodesError([[null, e]], []);\n\n      const innerErrors = error.errors;\n      for (const [file, e] of innerErrors) {\n        if (file) {\n          errorBodyLines.push(`  - ${file}: ${e.message}`);\n        } else {\n          errorBodyLines.push(`  - ${e.message}`);\n        }\n        if (e.stack) {\n          const innerStackTrace = '    ' + e.stack.split('\\n')?.join('\\n    ');\n          errorBodyLines.push(innerStackTrace);\n        }\n      }\n\n      error.stack = errorBodyLines.join('\\n');\n\n      // This represents a single plugin erroring out with a hard error.\n      errors.push(error);\n      // The plugin didn't return partial results, so we return an empty array.\n      return error.partialResults.map((r) => [pluginName, r[0], r[1]] as const);\n    });\n\n    results.push(r);\n  }\n\n  return Promise.all(results).then((results) => {\n    const { projectRootMap, externalNodes, rootMap, configurationSourceMaps } =\n      mergeCreateNodesResults(results, nxJson, errors);\n\n    performance.mark('build-project-configs:end');\n    performance.measure(\n      'build-project-configs',\n      'build-project-configs:start',\n      'build-project-configs:end'\n    );\n\n    if (errors.length === 0) {\n      return {\n        projects: projectRootMap,\n        externalNodes,\n        projectRootMap: rootMap,\n        sourceMaps: configurationSourceMaps,\n        matchingProjectFiles: projectFiles,\n      };\n    } else {\n      throw new ProjectConfigurationsError(errors, {\n        projects: projectRootMap,\n        externalNodes,\n        projectRootMap: rootMap,\n        sourceMaps: configurationSourceMaps,\n        matchingProjectFiles: projectFiles,\n      });\n    }\n  });\n}\n\nfunction mergeCreateNodesResults(\n  results: (readonly [\n    plugin: string,\n    file: string,\n    result: CreateNodesResult\n  ])[][],\n  nxJsonConfiguration: NxJsonConfiguration,\n  errors: (\n    | AggregateCreateNodesError\n    | MergeNodesError\n    | ProjectsWithNoNameError\n    | MultipleProjectsWithSameNameError\n  )[]\n) {\n  performance.mark('createNodes:merge - start');\n  const projectRootMap: Record<string, ProjectConfiguration> = {};\n  const externalNodes: Record<string, ProjectGraphExternalNode> = {};\n  const configurationSourceMaps: Record<\n    string,\n    Record<string, SourceInformation>\n  > = {};\n\n  for (const result of results.flat()) {\n    const [pluginName, file, nodes] = result;\n\n    const { projects: projectNodes, externalNodes: pluginExternalNodes } =\n      nodes;\n\n    const sourceInfo: SourceInformation = [file, pluginName];\n\n    for (const node in projectNodes) {\n      // Handles `{projects: {'libs/foo': undefined}}`.\n      if (!projectNodes[node]) {\n        continue;\n      }\n      const project = {\n        root: node,\n        ...projectNodes[node],\n      };\n      try {\n        mergeProjectConfigurationIntoRootMap(\n          projectRootMap,\n          project,\n          configurationSourceMaps,\n          sourceInfo\n        );\n      } catch (error) {\n        errors.push(\n          new MergeNodesError({\n            file,\n            pluginName,\n            error,\n          })\n        );\n      }\n    }\n    Object.assign(externalNodes, pluginExternalNodes);\n  }\n\n  try {\n    validateAndNormalizeProjectRootMap(\n      projectRootMap,\n      nxJsonConfiguration,\n      configurationSourceMaps\n    );\n  } catch (e) {\n    if (\n      isProjectsWithNoNameError(e) ||\n      isMultipleProjectsWithSameNameError(e)\n    ) {\n      errors.push(e);\n    } else {\n      throw e;\n    }\n  }\n\n  const rootMap = createRootMap(projectRootMap);\n\n  performance.mark('createNodes:merge - end');\n  performance.measure(\n    'createNodes:merge',\n    'createNodes:merge - start',\n    'createNodes:merge - end'\n  );\n  return { projectRootMap, externalNodes, rootMap, configurationSourceMaps };\n}\n\nexport function findMatchingConfigFiles(\n  projectFiles: string[],\n  pattern: string,\n  include: string[],\n  exclude: string[]\n): string[] {\n  const matchingConfigFiles: string[] = [];\n\n  for (const file of projectFiles) {\n    if (minimatch(file, pattern, { dot: true })) {\n      if (include) {\n        const included = include.some((includedPattern) =>\n          minimatch(file, includedPattern, { dot: true })\n        );\n        if (!included) {\n          continue;\n        }\n      }\n\n      if (exclude) {\n        const excluded = exclude.some((excludedPattern) =>\n          minimatch(file, excludedPattern, { dot: true })\n        );\n        if (excluded) {\n          continue;\n        }\n      }\n\n      matchingConfigFiles.push(file);\n    }\n  }\n  return matchingConfigFiles;\n}\n\nexport function readProjectConfigurationsFromRootMap(\n  projectRootMap: Record<string, ProjectConfiguration>\n) {\n  const projects: Record<string, ProjectConfiguration> = {};\n  // If there are projects that have the same name, that is an error.\n  // This object tracks name -> (all roots of projects with that name)\n  // to provide better error messaging.\n  const conflicts = new Map<string, string[]>();\n  const projectRootsWithNoName: string[] = [];\n\n  for (const root in projectRootMap) {\n    const project = projectRootMap[root];\n    // We're setting `// targets` as a comment `targets` is empty due to Project Crystal.\n    // Strip it before returning configuration for usage.\n    if (project['// targets']) delete project['// targets'];\n\n    try {\n      validateProject(project, projects);\n      projects[project.name] = project;\n    } catch (e) {\n      if (isProjectWithNoNameError(e)) {\n        projectRootsWithNoName.push(e.projectRoot);\n      } else if (isProjectWithExistingNameError(e)) {\n        const rootErrors = conflicts.get(e.projectName) ?? [\n          projects[e.projectName].root,\n        ];\n        rootErrors.push(e.projectRoot);\n        conflicts.set(e.projectName, rootErrors);\n      } else {\n        throw e;\n      }\n    }\n  }\n\n  if (conflicts.size > 0) {\n    throw new MultipleProjectsWithSameNameError(conflicts, projects);\n  }\n  if (projectRootsWithNoName.length > 0) {\n    throw new ProjectsWithNoNameError(projectRootsWithNoName, projects);\n  }\n  return projects;\n}\n\nfunction validateAndNormalizeProjectRootMap(\n  projectRootMap: Record<string, ProjectConfiguration>,\n  nxJsonConfiguration: NxJsonConfiguration,\n  sourceMaps: ConfigurationSourceMaps = {}\n) {\n  // Name -> Project, used to validate that all projects have unique names\n  const projects: Record<string, ProjectConfiguration> = {};\n  // If there are projects that have the same name, that is an error.\n  // This object tracks name -> (all roots of projects with that name)\n  // to provide better error messaging.\n  const conflicts = new Map<string, string[]>();\n  const projectRootsWithNoName: string[] = [];\n\n  for (const root in projectRootMap) {\n    const project = projectRootMap[root];\n    // We're setting `// targets` as a comment `targets` is empty due to Project Crystal.\n    // Strip it before returning configuration for usage.\n    if (project['// targets']) delete project['// targets'];\n\n    try {\n      validateProject(project, projects);\n      projects[project.name] = project;\n    } catch (e) {\n      if (isProjectWithNoNameError(e)) {\n        projectRootsWithNoName.push(e.projectRoot);\n      } else if (isProjectWithExistingNameError(e)) {\n        const rootErrors = conflicts.get(e.projectName) ?? [\n          projects[e.projectName].root,\n        ];\n        rootErrors.push(e.projectRoot);\n        conflicts.set(e.projectName, rootErrors);\n      } else {\n        throw e;\n      }\n    }\n\n    normalizeTargets(project, sourceMaps, nxJsonConfiguration);\n  }\n\n  if (conflicts.size > 0) {\n    throw new MultipleProjectsWithSameNameError(conflicts, projects);\n  }\n  if (projectRootsWithNoName.length > 0) {\n    throw new ProjectsWithNoNameError(projectRootsWithNoName, projects);\n  }\n  return projectRootMap;\n}\n\nfunction normalizeTargets(\n  project: ProjectConfiguration,\n  sourceMaps: ConfigurationSourceMaps,\n  nxJsonConfiguration: NxJsonConfiguration<'*' | string[]>\n) {\n  for (const targetName in project.targets) {\n    project.targets[targetName] = normalizeTarget(\n      project.targets[targetName],\n      project\n    );\n\n    const projectSourceMaps = sourceMaps[project.root];\n\n    const targetConfig = project.targets[targetName];\n    const targetDefaults = deepClone(\n      readTargetDefaultsForTarget(\n        targetName,\n        nxJsonConfiguration.targetDefaults,\n        targetConfig.executor\n      )\n    );\n\n    // We only apply defaults if they exist\n    if (targetDefaults && isCompatibleTarget(targetConfig, targetDefaults)) {\n      project.targets[targetName] = mergeTargetDefaultWithTargetDefinition(\n        targetName,\n        project,\n        normalizeTarget(targetDefaults, project),\n        projectSourceMaps\n      );\n    }\n\n    if (\n      // If the target has no executor or command, it doesn't do anything\n      !project.targets[targetName].executor &&\n      !project.targets[targetName].command\n    ) {\n      // But it may have dependencies that do something\n      if (\n        project.targets[targetName].dependsOn &&\n        project.targets[targetName].dependsOn.length > 0\n      ) {\n        project.targets[targetName].executor = 'nx:noop';\n      } else {\n        // If it does nothing, and has no depenencies,\n        // we can remove it.\n        delete project.targets[targetName];\n      }\n    }\n  }\n}\n\nexport function validateProject(\n  project: ProjectConfiguration,\n  // name -> project\n  knownProjects: Record<string, ProjectConfiguration>\n) {\n  if (!project.name) {\n    try {\n      const { name } = readJsonFile(join(project.root, 'package.json'));\n      if (!name) {\n        throw new Error(`Project at ${project.root} has no name provided.`);\n      }\n      project.name = name;\n    } catch {\n      throw new ProjectWithNoNameError(project.root);\n    }\n  } else if (\n    knownProjects[project.name] &&\n    knownProjects[project.name].root !== project.root\n  ) {\n    throw new ProjectWithExistingNameError(project.name, project.root);\n  }\n}\n\nfunction targetDefaultShouldBeApplied(\n  key: string,\n  sourceMap: Record<string, SourceInformation>\n) {\n  const sourceInfo = sourceMap[key];\n  if (!sourceInfo) {\n    return true;\n  }\n  // The defined value of the target is from a plugin that\n  // isn't part of Nx's core plugins, so target defaults are\n  // applied on top of it.\n  const [, plugin] = sourceInfo;\n  return !plugin?.startsWith('nx/');\n}\n\nfunction deepClone(obj) {\n  return JSON.parse(JSON.stringify(obj));\n}\n\nexport function mergeTargetDefaultWithTargetDefinition(\n  targetName: string,\n  project: ProjectConfiguration,\n  targetDefault: Partial<TargetConfiguration>,\n  sourceMap: Record<string, SourceInformation>\n): TargetConfiguration {\n  const targetDefinition = project.targets[targetName] ?? {};\n  const result = deepClone(targetDefinition);\n\n  for (const key in targetDefault) {\n    switch (key) {\n      case 'options': {\n        const normalizedDefaults = resolveNxTokensInOptions(\n          targetDefault.options,\n          project,\n          targetName\n        );\n        for (const optionKey in normalizedDefaults) {\n          const sourceMapKey = `targets.${targetName}.options.${optionKey}`;\n          if (\n            targetDefinition.options[optionKey] === undefined ||\n            targetDefaultShouldBeApplied(sourceMapKey, sourceMap)\n          ) {\n            result.options[optionKey] = targetDefault.options[optionKey];\n            sourceMap[sourceMapKey] = ['nx.json', 'nx/target-defaults'];\n          }\n        }\n        break;\n      }\n      case 'configurations': {\n        if (!result.configurations) {\n          result.configurations = {};\n          sourceMap[`targets.${targetName}.configurations`] = [\n            'nx.json',\n            'nx/target-defaults',\n          ];\n        }\n        for (const configuration in targetDefault.configurations) {\n          if (!result.configurations[configuration]) {\n            result.configurations[configuration] = {};\n            sourceMap[`targets.${targetName}.configurations.${configuration}`] =\n              ['nx.json', 'nx/target-defaults'];\n          }\n          const normalizedConfigurationDefaults = resolveNxTokensInOptions(\n            targetDefault.configurations[configuration],\n            project,\n            targetName\n          );\n          for (const configurationKey in normalizedConfigurationDefaults) {\n            const sourceMapKey = `targets.${targetName}.configurations.${configuration}.${configurationKey}`;\n            if (\n              targetDefinition.configurations?.[configuration]?.[\n                configurationKey\n              ] === undefined ||\n              targetDefaultShouldBeApplied(sourceMapKey, sourceMap)\n            ) {\n              result.configurations[configuration][configurationKey] =\n                targetDefault.configurations[configuration][configurationKey];\n              sourceMap[sourceMapKey] = ['nx.json', 'nx/target-defaults'];\n            }\n          }\n        }\n        break;\n      }\n      default: {\n        const sourceMapKey = `targets.${targetName}.${key}`;\n        if (\n          targetDefinition[key] === undefined ||\n          targetDefaultShouldBeApplied(sourceMapKey, sourceMap)\n        ) {\n          result[key] = targetDefault[key];\n          sourceMap[sourceMapKey] = ['nx.json', 'nx/target-defaults'];\n        }\n        break;\n      }\n    }\n  }\n  return result;\n}\n\n/**\n * Merges two targets.\n *\n * Most properties from `target` will overwrite any properties from `baseTarget`.\n * Options and configurations are treated differently - they are merged together if the executor definition is compatible.\n *\n * @param target The target definition with higher priority\n * @param baseTarget The target definition that should be overwritten. Can be undefined, in which case the target is returned as-is.\n * @param projectConfigSourceMap The source map to be filled with metadata about where each property came from\n * @param sourceInformation The metadata about where the new target was defined\n * @param targetIdentifier The identifier for the target to merge, used for source map\n * @returns A merged target configuration\n */\nexport function mergeTargetConfigurations(\n  target: TargetConfiguration,\n  baseTarget?: TargetConfiguration,\n  projectConfigSourceMap?: Record<string, SourceInformation>,\n  sourceInformation?: SourceInformation,\n  targetIdentifier?: string\n): TargetConfiguration {\n  const {\n    configurations: defaultConfigurations,\n    options: defaultOptions,\n    ...baseTargetProperties\n  } = baseTarget ?? {};\n\n  // Target is \"compatible\", e.g. executor is defined only once or is the same\n  // in both places. This means that it is likely safe to merge\n  const isCompatible = isCompatibleTarget(baseTarget ?? {}, target);\n\n  if (!isCompatible && projectConfigSourceMap) {\n    // if the target is not compatible, we will simply override the options\n    // we have to delete old entries from the source map\n    for (const key in projectConfigSourceMap) {\n      if (key.startsWith(`${targetIdentifier}`)) {\n        delete projectConfigSourceMap[key];\n      }\n    }\n  }\n\n  // merge top level properties if they're compatible\n  const result = {\n    ...(isCompatible ? baseTargetProperties : {}),\n    ...target,\n  };\n\n  // record top level properties in source map\n  if (projectConfigSourceMap) {\n    projectConfigSourceMap[targetIdentifier] = sourceInformation;\n\n    // record root level target properties to source map\n    for (const targetProperty in target) {\n      const targetPropertyId = `${targetIdentifier}.${targetProperty}`;\n      projectConfigSourceMap[targetPropertyId] = sourceInformation;\n    }\n  }\n\n  // merge options if there are any\n  // if the targets aren't compatible, we simply discard the old options during the merge\n  if (target.options || defaultOptions) {\n    result.options = mergeOptions(\n      target.options,\n      isCompatible ? defaultOptions : undefined,\n      projectConfigSourceMap,\n      sourceInformation,\n      targetIdentifier\n    );\n  }\n\n  // merge configurations if there are any\n  // if the targets aren't compatible, we simply discard the old configurations during the merge\n  if (target.configurations || defaultConfigurations) {\n    result.configurations = mergeConfigurations(\n      target.configurations,\n      isCompatible ? defaultConfigurations : undefined,\n      projectConfigSourceMap,\n      sourceInformation,\n      targetIdentifier\n    );\n  }\n\n  if (target.metadata) {\n    result.metadata = mergeMetadata(\n      projectConfigSourceMap,\n      sourceInformation,\n      `${targetIdentifier}.metadata`,\n      target.metadata,\n      baseTarget?.metadata\n    );\n  }\n\n  return result as TargetConfiguration;\n}\n\n/**\n * Checks if targets options are compatible - used