ror\n      | MultipleProjectsWithSameNameError\n    >,\n    public readonly partialProjectConfigurationsResult: ConfigurationResult\n  ) {\n    super('Failed to create project configurations');\n    this.name = this.constructor.name;\n  }\n}\n\nexport function isProjectConfigurationsError(\n  e: unknown\n): e is ProjectConfigurationsError {\n  return (\n    e instanceof ProjectConfigurationsError ||\n    (typeof e === 'object' &&\n      'name' in e &&\n      e?.name === ProjectConfigurationsError.name)\n  );\n}\n\n/**\n * This error should be thrown when a `createNodesV2` function hits a recoverable error.\n * It allows Nx to recieve partial results and continue processing for better UX.\n */\nexport class AggregateCreateNodesError extends Error {\n  /**\n   * Throwing this error from a `createNodesV2` function will allow Nx to continue processing and recieve partial results from your plugin.\n   * @example\n   * export async function createNodesV2(\n   *  files: string[],\n   * ) {\n   *   const partialResults = [];\n   *   const errors = [];\n   *   await Promise.all(files.map(async (file) => {\n   *     try {\n   *        const result = await createNodes(file);\n   *        partialResults.push(result);\n   *     } catch (e) {\n   *        errors.push([file, e]);\n   *     }\n   *   }));\n   *  if (errors.length > 0) {\n   *     throw new AggregateCreateNodesError(errors, partialResults);\n   *   }\n   *   return partialResults;\n   * }\n   *\n   * @param errors An array of tuples that represent errors encountered when processing a given file. An example entry might look like ['path/to/project.json', [Error: 'Invalid JSON. Unexpected token 'a' in JSON at position 0]]\n   * @param partialResults The partial results of the `createNodesV2` function. This should be the results for each file that didn't encounter an issue.\n   */\n  constructor(\n    public readonly errors: Array<[file: string | null, error: Error]>,\n    public readonly partialResults: Awaited<ReturnType<CreateNodesFunctionV2>>\n  ) {\n    super('Failed to create nodes');\n    this.name = this.constructor.name;\n    if (\n      // Errors should be an array\n      !Array.isArray(errors) ||\n      !errors.every(\n        // Where every element is a tuple\n        (errorTuple) =>\n          Array.isArray(errorTuple) &&\n          // That has a length of 2\n          errorTuple.length === 2\n      )\n    ) {\n      throw new Error(\n        'AggregateCreateNodesError must be constructed with an array of tuples where the first element is a filename or undefined and the second element is the underlying error.'\n      );\n    }\n  }\n}\n\nexport class MergeNodesError extends Error {\n  file: string;\n  pluginName: string;\n\n  constructor({\n    file,\n    pluginName,\n    error,\n  }: {\n    file: string;\n    pluginName: string;\n    error: Error;\n  }) {\n    const msg = `The nodes created from ${file} by the \"${pluginName}\" could not be merged into the project graph:`;\n\n    super(msg, { cause: error });\n    this.name = this.constructor.name;\n    this.file = file;\n    this.pluginName = pluginName;\n    this.stack = `${this.message}\\n${indentString(\n      formatErrorStackAndCause(error),\n      2\n    )}`;\n  }\n}\n\nexport class CreateMetadataError extends Error {\n  constructor(public readonly error: Error, public readonly plugin: string) {\n    super(\n      `The \"${plugin}\" plugin threw an error while creating metadata: ${error.message}`,\n      {\n        cause: error,\n      }\n    );\n    this.name = this.constructor.name;\n  }\n}\n\nexport class ProcessDependenciesError extends Error {\n  constructor(public readonly pluginName: string, { cause }) {\n    super(\n      `The \"${pluginName}\" plugin threw an error while creating dependencies: ${cause.message}`,\n      {\n        cause,\n      }\n    );\n    this.name = this.constructor.name;\n    this.stack = `${this.message}\\n  ${cause.stack.split('\\n').join('\\n  ')}`;\n  }\n}\nexport class WorkspaceValidityError extends Error {\n  constructor(public message: string) {\n    message = `Configuration Error\\n${message}`;\n    super(message);\n    this.name = this.constructor.name;\n  }\n}\n\nexport function isWorkspaceValidityError(\n  e: unknown\n): e is WorkspaceValidityError {\n  return (\n    e instanceof WorkspaceValidityError ||\n    (typeof e === 'object' &&\n      'name' in e &&\n      e?.name === WorkspaceValidityError.name)\n  );\n}\nexport class AggregateProjectGraphError extends Error {\n  constructor(\n    public readonly errors: Array<\n      CreateMetadataError | ProcessDependenciesError | WorkspaceValidityError\n    >,\n    public readonly partialProjectGraph: ProjectGraph\n  ) {\n    super('Failed to create project graph. See above for errors');\n    this.name = this.constructor.name;\n  }\n}\n\nexport function isAggregateProjectGraphError(\n  e: unknown\n): e is AggregateProjectGraphError {\n  return (\n    e instanceof AggregateProjectGraphError ||\n    (typeof e === 'object' &&\n      'name' in e &&\n      e?.name === AggregateProjectGraphError.name)\n  );\n}\n\nexport function isCreateMetadataError(e: unknown): e is CreateMetadataError {\n  return (\n    e instanceof CreateMetadataError ||\n    (typeof e === 'object' &&\n      'name' in e &&\n      e?.name === CreateMetadataError.name)\n  );\n}\n\nexport function isAggregateCreateNodesError(\n  e: unknown\n): e is AggregateCreateNodesError {\n  return (\n    e instanceof AggregateCreateNodesError ||\n    (typeof e === 'object' &&\n      'name' in e &&\n      e?.name === AggregateCreateNodesError.name)\n  );\n}\n\nexport function isMergeNodesError(e: unknown): e is MergeNodesError {\n  return (\n    e instanceof MergeNodesError ||\n    (typeof e === 'object' && 'name' in e && e?.name === MergeNodesError.name)\n  );\n}\n\nexport class DaemonProjectGraphError extends Error {\n  constructor(\n    public errors: any[],\n    readonly projectGraph: ProjectGraph,\n    readonly sourceMaps: ConfigurationSourceMaps\n  ) {\n    super(\n      `The Daemon Process threw an error while calculating the project graph. Convert this error to a ProjectGraphError to get more information.`\n    );\n    this.name = this.constructor.name;\n  }\n}\n\nexport class LoadPluginError extends Error {\n  constructor(public plugin: string, cause: Error) {\n    super(`Could not load plugin ${plugin}`, {\n      cause,\n    });\n    this.name = this.constructor.name;\n  }\n}\n\nfunction indentString(str: string, indent: number): string {\n  return (\n    ' '.repeat(indent) +\n    str\n      .split('\\n')\n      .map((line) => ' '.repeat(indent) + line)\n      .join('\\n')\n  );\n}\n\nfunction formatErrorStackAndCause(error: Error): string {\n  const cause =\n    error.cause && error.cause instanceof Error ? error.cause : null;\n  return (\n    error.stack +\n    (cause\n      ? `\\nCaused by: \\n${indentString(cause.stack ?? cause.message, 2)}`\n      : '')\n  );\n}\n","resolvedModuleNames":["/workspace/repo/packages/nx/src/project-graph/utils/project-configuration-utils.ts","/workspace/repo/packages/nx/src/config/workspace-json-project-json.ts","/workspace/repo/packages/nx/src/config/project-graph.ts","/workspace/repo/packages/nx/src/project-graph/plugins/public-api.ts","/workspace/repo/packages/nx/src/config/nx-json.ts","/workspace/repo/packages/nx/src/utils/logger.ts","/workspace/repo/packages/nx/src/utils/fileutils.ts","/workspace/repo/packages/nx/src/utils/workspace-root.ts","/workspace/repo/packages/nx/src/project-graph/plugins/internal-api.ts","/workspace/repo/packages/nx/src/project-graph/error-types.ts","/workspace/repo/packages/nx/src/utils/globs.ts","/workspace/repo/packages/nx/src/project-graph/project-graph-builder.ts"]}],["/workspace/repo/packages/nx/src/utils/package-manager.ts",{"fileContent":"import { exec, execSync } from 'child_process';\nimport { copyFileSync, existsSync, writeFileSync } from 'fs';\nimport {\n  Pair,\n  ParsedNode,\n  parseDocument,\n  stringify as YAMLStringify,\n  YAMLMap,\n  YAMLSeq,\n  Scalar,\n} from 'yaml';\nimport { rm } from 'node:fs/promises';\nimport { dirname, join, relative } from 'path';\nimport { gte, lt } from 'semver';\nimport { dirSync } from 'tmp';\nimport { promisify } from 'util';\n\nimport { readNxJson } from '../config/configuration';\nimport { readPackageJson } from '../project-graph/file-utils';\nimport {\n  readFileIfExisting,\n  readJsonFile,\n  readYamlFile,\n  writeJsonFile,\n} from './fileutils';\nimport { PackageJson, readModulePackageJson } from './package-json';\nimport { workspaceRoot } from './workspace-root';\n\nconst execAsync = promisify(exec);\n\nexport type PackageManager = 'yarn' | 'pnpm' | 'npm' | 'bun';\n\nexport interface PackageManagerCommands {\n  preInstall?: string;\n  install: string;\n  ciInstall: string;\n  updateLockFile: string;\n  add: string;\n  addDev: string;\n  rm: string;\n  exec: string;\n  dlx: string;\n  list: string;\n  run: (script: string, args?: string) => string;\n  // Make this required once bun adds programatically support for reading config https://github.com/oven-sh/bun/issues/7140\n  getRegistryUrl?: string;\n}\n\n/**\n * Detects which package manager is used in the workspace based on the lock file.\n */\nexport function detectPackageManager(dir: string = ''): PackageManager {\n  const nxJson = readNxJson();\n  return (\n    nxJson.cli?.packageManager ??\n    (existsSync(join(dir, 'bun.lockb'))\n      ? 'bun'\n      : existsSync(join(dir, 'yarn.lock'))\n      ? 'yarn'\n      : existsSync(join(dir, 'pnpm-lock.yaml'))\n      ? 'pnpm'\n      : 'npm')\n  );\n}\n\n/**\n * Returns true if the workspace is using npm workspaces, yarn workspaces, or pnpm workspaces.\n * @param packageManager The package manager to use. If not provided, it will be detected based on the lock file.\n * @param root The directory the commands will be ran inside of. Defaults to the current workspace's root.\n */\nexport function isWorkspacesEnabled(\n  packageManager: PackageManager = detectPackageManager(),\n  root: string = workspaceRoot\n): boolean {\n  if (packageManager === 'pnpm') {\n    return existsSync(join(root, 'pnpm-workspace.yaml'));\n  }\n\n  // yarn and npm both use the same 'workspaces' property in package.json\n  const packageJson: PackageJson = readPackageJson(root);\n  return !!packageJson?.workspaces;\n}\n\n/**\n * Returns commands for the package manager used in the workspace.\n * By default, the package manager is derived based on the lock file,\n * but it can also be passed in explicitly.\n *\n * Example:\n *\n * ```javascript\n * execSync(`${getPackageManagerCommand().addDev} my-dev-package`);\n * ```\n *\n * @param packageManager The package manager to use. If not provided, it will be detected based on the lock file.\n * @param root The directory the commands will be ran inside of. Defaults to the current workspace's root.\n */\nexport function getPackageManagerCommand(\n  packageManager: PackageManager = detectPackageManager(),\n  root: string = workspaceRoot\n): PackageManagerCommands {\n  const commands: { [pm in PackageManager]: () => PackageManagerCommands } = {\n    yarn: () => {\n      let yarnVersion: string, useBerry: boolean;\n      try {\n        yarnVersion = getPackageManagerVersion('yarn', root);\n        useBerry = gte(yarnVersion, '2.0.0');\n      } catch {\n        yarnVersion = 'latest';\n        useBerry = true;\n      }\n\n      return {\n        preInstall: `yarn set version ${yarnVersion}`,\n        install: 'yarn',\n        ciInstall: useBerry\n          ? 'yarn install --immutable'\n          : 'yarn install --frozen-lockfile',\n        updateLockFile: useBerry\n          ? 'yarn install --mode update-lockfile'\n          : 'yarn install',\n        add: useBerry ? 'yarn add' : 'yarn add -W',\n        addDev: useBerry ? 'yarn add -D' : 'yarn add -D -W',\n        rm: 'yarn remove',\n        exec: 'yarn',\n        dlx: useBerry ? 'yarn dlx' : 'yarn',\n        run: (script: string, args?: string) =>\n          `yarn ${script}${args ? ` ${args}` : ''}`,\n        list: useBerry ? 'yarn info --name-only' : 'yarn list',\n        getRegistryUrl: useBerry\n          ? 'yarn config get npmRegistryServer'\n          : 'yarn config get registry',\n      };\n    },\n    pnpm: () => {\n      let modernPnpm: boolean, includeDoubleDashBeforeArgs: boolean;\n      try {\n        const pnpmVersion = getPackageManagerVersion('pnpm', root);\n        modernPnpm = gte(pnpmVersion, '6.13.0');\n        includeDoubleDashBeforeArgs = lt(pnpmVersion, '7.0.0');\n      } catch {\n        modernPnpm = true;\n        includeDoubleDashBeforeArgs = true;\n      }\n\n      const isPnpmWorkspace = existsSync(join(root, 'pnpm-workspace.yaml'));\n      return {\n        install: 'pnpm install --no-frozen-lockfile', // explicitly disable in case of CI\n        ciInstall: 'pnpm install --frozen-lockfile',\n        updateLockFile: 'pnpm install --lockfile-only',\n        add: isPnpmWorkspace ? 'pnpm add -w' : 'pnpm add',\n        addDev: isPnpmWorkspace ? 'pnpm add -Dw' : 'pnpm add -D',\n        rm: 'pnpm rm',\n        exec: modernPnpm ? 'pnpm exec' : 'pnpx',\n        dlx: modernPnpm ? 'pnpm dlx' : 'pnpx',\n        run: (script: string, args?: string) =>\n          `pnpm run ${script}${\n            args\n              ? includeDoubleDashBeforeArgs\n                ? ' -- ' + args\n                : ` ${args}`\n              : ''\n          }`,\n        list: 'pnpm ls --depth 100',\n        getRegistryUrl: 'pnpm config get registry',\n      };\n    },\n    npm: () => {\n      // TODO: Remove this\n      process.env.npm_config_legacy_peer_deps ??= 'true';\n\n      return {\n        install: 'npm install',\n        ciInstall: 'npm ci --legacy-peer-deps',\n        updateLockFile: 'npm install --package-lock-only',\n        add: 'npm install',\n        addDev: 'npm install -D',\n        rm: 'npm rm',\n        exec: 'npx',\n        dlx: 'npx',\n        run: (script: string, args?: string) =>\n          `npm run ${script}${args ? ' -- ' + args : ''}`,\n        list: 'npm ls',\n        getRegistryUrl: 'npm config get registry',\n      };\n    },\n    bun: () => {\n      // bun doesn't current support programatically reading config https://github.com/oven-sh/bun/issues/7140\n      return {\n        install: 'bun install',\n        ciInstall: 'bun install --no-cache',\n        updateLockFile: 'bun install --frozen-lockfile',\n        add: 'bun install',\n        addDev: 'bun install -D',\n        rm: 'bun rm',\n        exec: 'bun',\n        dlx: 'bunx',\n        run: (script: string, args: string) => `bun run ${script} -- ${args}`,\n        list: 'bun pm ls',\n      };\n    },\n  };\n\n  return commands[packageManager]();\n}\n\n/**\n * Returns the version of the package manager used in the workspace.\n * By default, the package manager is derived based on the lock file,\n * but it can also be passed in explicitly.\n */\nexport function getPackageManagerVersion(\n  packageManager: PackageManager = detectPackageManager(),\n  cwd = process.cwd()\n): string {\n  let version;\n  try {\n    version = execSync(`${packageManager} --version`, {\n      cwd,\n      encoding: 'utf-8',\n      windowsHide: true,\n    }).trim();\n  } catch {\n    if (existsSync(join(cwd, 'package.json'))) {\n      const packageVersion = readJsonFile<PackageJson>(\n        join(cwd, 'package.json')\n      )?.packageManager;\n      if (packageVersion) {\n        const [packageManagerFromPackageJson, versionFromPackageJson] =\n          packageVersion.split('@');\n        if (\n          packageManagerFromPackageJson === packageManager &&\n          versionFromPackageJson\n        ) {\n          version = versionFromPackageJson;\n        }\n      }\n    }\n  }\n  if (!version) {\n    throw new Error(`Cannot determine the version of ${packageManager}.`);\n  }\n  return version;\n}\n\n/**\n * Checks for a project level npmrc file by crawling up the file tree until\n * hitting a package.json file, as this is how npm finds them as well.\n */\nexport function findFileInPackageJsonDirectory(\n  file: string,\n  directory: string = process.cwd()\n): string | null {\n  while (!existsSync(join(directory, 'package.json'))) {\n    directory = dirname(directory);\n  }\n  const path = join(directory, file);\n  return existsSync(path) ? path : null;\n}\n\n/**\n * We copy yarnrc.yml to the temporary directory to ensure things like the specified\n * package registry are still used. However, there are a few relative paths that can\n * cause issues, so we modify them to fit the new directory.\n *\n * Exported for testing - not meant to be used outside of this file.\n *\n * @param contents The string contents of the yarnrc.yml file\n * @returns Updated string contents of the yarnrc.yml file\n */\nexport function modifyYarnRcYmlToFitNewDirectory(contents: string): string {\n  const { parseSyml, stringifySyml } = require('@yarnpkg/parsers');\n  const parsed: {\n    yarnPath?: string;\n    plugins?: (string | { path: string; spec: string })[];\n  } = parseSyml(contents);\n\n  if (parsed.yarnPath) {\n    // yarnPath is relative to the workspace root, so we need to make it relative\n    // to the new directory s.t. it still points to the same yarn binary.\n    delete parsed.yarnPath;\n  }\n  if (parsed.plugins) {\n    // Plugins specified by a string are relative paths from workspace root.\n    // ex: https://yarnpkg.com/advanced/plugin-tutorial#writing-our-first-plugin\n    delete parsed.plugins;\n  }\n  return stringifySyml(parsed);\n}\n\n/**\n * We copy .yarnrc to the temporary directory to ensure things like the specified\n * package registry are still used. However, there are a few relative paths that can\n * cause issues, so we modify them to fit the new directory.\n *\n * Exported for testing - not meant to be used outside of this file.\n *\n * @param contents The string contents of the yarnrc.yml file\n * @returns Updated string contents of the yarnrc.yml file\n */\nexport function modifyYarnRcToFitNewDirectory(contents: string): string {\n  const lines = contents.split('\\n');\n  const yarnPathIndex = lines.findIndex((line) => line.startsWith('yarn-path'));\n  if (yarnPathIndex !== -1) {\n    lines.splice(yarnPathIndex, 1);\n  }\n  return lines.join('\\n');\n}\n\nexport function copyPackageManagerConfigurationFiles(\n  root: string,\n  destination: string\n) {\n  for (const packageManagerConfigFile of [\n    '.npmrc',\n    '.yarnrc',\n    '.yarnrc.yml',\n    'bunfig.toml',\n  ]) {\n    // f is an absolute path, including the {workspaceRoot}.\n    const f = findFileInPackageJsonDirectory(packageManagerConfigFile, root);\n    if (f) {\n      // Destination should be the same relative path from the {workspaceRoot},\n      // but now relative to the destination. `relative` makes `{workspaceRoot}/some/path`\n      // look like `./some/path`, and joining that gets us `{destination}/some/path\n      const destinationPath = join(destination, relative(root, f));\n      switch (packageManagerConfigFile) {\n        case '.npmrc': {\n          copyFileSync(f, destinationPath);\n          break;\n        }\n        case '.yarnrc': {\n          const updated = modifyYarnRcToFitNewDirectory(readFileIfExisting(f));\n          writeFileSync(destinationPath, updated);\n          break;\n        }\n        case '.yarnrc.yml': {\n          const updated = modifyYarnRcYmlToFitNewDirectory(\n            readFileIfExisting(f)\n          );\n          writeFileSync(destinationPath, updated);\n          break;\n        }\n        case 'bunfig.toml': {\n          copyFileSync(f, destinationPath);\n          break;\n        }\n      }\n    }\n  }\n}\n\n/**\n * Creates a temporary directory where you can run package manager commands safely.\n *\n * For cases where you'd want to install packages that require an `.npmrc` set up,\n * this function looks up for the nearest `.npmrc` (if exists) and copies it over to the\n * temp directory.\n */\nexport function createTempNpmDirectory() {\n  const dir = dirSync().name;\n\n  // A package.json is needed for pnpm pack and for .npmrc to resolve\n  writeJsonFile(`${dir}/package.json`, {});\n  copyPackageManagerConfigurationFiles(workspaceRoot, dir);\n\n  const cleanup = async () => {\n    try {\n      await rm(dir, { recursive: true, force: true });\n    } catch {\n      // It's okay if this fails, the OS will clean it up eventually\n    }\n  };\n\n  return { dir, cleanup };\n}\n\n/**\n * Returns the resolved version for a given package and version tag using the\n * NPM registry (when using Yarn it will fall back to NPM to fetch the info).\n */\nexport async function resolvePackageVersionUsingRegistry(\n  packageName: string,\n  version: string\n): Promise<string> {\n  try {\n    const result = await packageRegistryView(packageName, version, 'version');\n\n    if (!result) {\n      throw new Error(`Unable to resolve version ${packageName}@${version}.`);\n    }\n\n    const lines = result.split('\\n');\n    if (lines.length === 1) {\n      return lines[0];\n    }\n\n    /**\n     * The output contains multiple lines ordered by release date, so the last\n     * version might not be the last one in the list. We need to sort it. Each\n     * line looks like:\n     *\n     * <package>@<version> '<version>'\n     */\n    const resolvedVersion = lines\n      .map((line) => line.split(' ')[1])\n      .sort()\n      .pop()\n      .replace(/'/g, '');\n\n    return resolvedVersion;\n  } catch {\n    throw new Error(`Unable to resolve version ${packageName}@${version}.`);\n  }\n}\n\n/**\n * Return the resolved version for a given package and version tag using by\n * installing it in a temporary directory and fetching the version from the\n * package.json.\n */\nexport async function resolvePackageVersionUsingInstallation(\n  packageName: string,\n  version: string\n): Promise<string> {\n  const { dir, cleanup } = createTempNpmDirectory();\n\n  try {\n    const pmc = getPackageManagerCommand();\n    await execAsync(`${pmc.add} ${packageName}@${version}`, {\n      cwd: dir,\n      windowsHide: true,\n    });\n\n    const { packageJson } = readModulePackageJson(packageName, [dir]);\n\n    return packageJson.version;\n  } finally {\n    await cleanup();\n  }\n}\n\nexport async function packageRegistryView(\n  pkg: string,\n  version: string,\n  args: string\n): Promise<string> {\n  let pm = detectPackageManager();\n  if (pm === 'yarn' || pm === 'bun') {\n    /**\n     * yarn has `yarn info` but it behaves differently than (p)npm,\n     * which makes it's usage unreliable\n     *\n     * @see https://github.com/nrwl/nx/pull/9667#discussion_r842553994\n     *\n     * Bun has a pm ls function but it only relates to its lockfile\n     * and acts differently from all other package managers\n     * from Jarred: \"it probably would be bun pm view <package-name>\"\n     */\n    pm = 'npm';\n  }\n\n  const { stdout } = await execAsync(`${pm} view ${pkg}@${version} ${args}`, {\n    windowsHide: true,\n  });\n  return stdout.toString().trim();\n}\n\nexport async function packageRegistryPack(\n  cwd: string,\n  pkg: string,\n  version: string\n): Promise<{ tarballPath: string }> {\n  let pm = detectPackageManager();\n  if (pm === 'yarn' || pm === 'bun') {\n    /**\n     * `(p)npm pack` will download a tarball of the specified version,\n     * whereas `yarn` pack creates a tarball of the active workspace, so it\n     * does not work for getting the content of a library.\n     *\n     * @see https://github.com/nrwl/nx/pull/9667#discussion_r842553994\n     *\n     * bun doesn't currently support pack\n     */\n    pm = 'npm';\n  }\n\n  const { stdout } = await execAsync(`${pm} pack ${pkg}@${version}`, {\n    cwd,\n    windowsHide: true,\n  });\n\n  const tarballPath = stdout.trim();\n  return { tarballPath };\n}\n\n/**\n * Gets the workspaces defined in the package manager configuration.\n * @returns workspaces defined in the package manager configuration, empty array if none are defined\n */\nexport function getPackageWorkspaces(\n  packageManager: PackageManager = detectPackageManager(),\n  root: string = workspaceRoot\n): string[] {\n  let workspaces: string[];\n\n  if (\n    packageManager === 'npm' ||\n    packageManager === 'yarn' ||\n    packageManager === 'bun'\n  ) {\n    const packageJson = readPackageJson(root);\n    workspaces = packageJson.workspaces;\n  } else if (packageManager === 'pnpm') {\n    const pnpmWorkspacePath = join(root, 'pnpm-workspace.yaml');\n    if (existsSync(pnpmWorkspacePath)) {\n      const { packages } =\n        readYamlFile<{ packages: string[] }>(pnpmWorkspacePath) ?? {};\n      workspaces = packages;\n    }\n  }\n\n  return workspaces ?? [];\n}\n\n/**\n * Adds a package to the workspaces defined in the package manager configuration.\n * If the package is already included in the workspaces, it will not be added again.\n * @param packageManager The package manager to use. If not provided, it will be detected based on the lock file.\n * @param workspaces The workspaces to add the package to. Defaults to the workspaces defined in the package manager configuration.\n * @param root The directory the commands will be ran inside of. Defaults to the current workspace's root.\n * @param packagePath The path of the package to add to the workspaces\n */\nexport function addPackagePathToWorkspaces(\n  packagePath: string,\n  packageManager: PackageManager = detectPackageManager(),\n  workspaces: string[] = getPackageWorkspaces(packageManager),\n  root: string = workspaceRoot\n): void {\n  if (\n    packageManager === 'npm' ||\n    packageManager === 'yarn' ||\n    packageManager === 'bun'\n  ) {\n    workspaces.push(packagePath);\n    const packageJson = readPackageJson(root);\n    const updatedPackageJson = {\n      ...packageJson,\n      workspaces,\n    };\n    const packageJsonPath = join(root, 'package.json');\n    writeJsonFile(packageJsonPath, updatedPackageJson);\n  } else if (packageManager === 'pnpm') {\n    const pnpmWorkspacePath = join(root, 'pnpm-workspace.yaml');\n    if (existsSync(pnpmWorkspacePath)) {\n      const pnpmWorkspaceDocument = parseDocument(\n        readFileIfExisting(pnpmWorkspacePath)\n      );\n      const pnpmWorkspaceContents: ParsedNode | null =\n        pnpmWorkspaceDocument.contents;\n      if (!pnpmWorkspaceContents) {\n        writeFileSync(\n          pnpmWorkspacePath,\n          YAMLStringify({\n            packages: [packagePath],\n          })\n        );\n      } else if (pnpmWorkspaceContents instanceof YAMLMap) {\n        const packages: Pair | undefined = pnpmWorkspaceContents.items.find(\n          (item: Pair) => {\n            return item.key instanceof Scalar\n              ? item.key?.value === 'packages'\n              : item.key === 'packages';\n          }\n        );\n        if (packages) {\n          if (packages.value instanceof YAMLSeq === false) {\n            packages.value = new YAMLSeq();\n          }\n          (packages.value as YAMLSeq).items ??= [];\n          (packages.value as YAMLSeq).items.push(packagePath);\n        } else {\n          // if the 'packages' key doesn't exist, create it\n          const packagesSeq = new YAMLSeq();\n          packagesSeq.items ??= [];\n          packagesSeq.items.push(packagePath);\n\n          pnpmWorkspaceDocument.add(\n            pnpmWorkspaceDocument.createPair('packages', packagesSeq)\n          );\n        }\n        writeFileSync(pnpmWorkspacePath, YAMLStringify(pnpmWorkspaceContents));\n      }\n    } else {\n      // If the file doesn't exist, create it\n      writeFileSync(\n        pnpmWorkspacePath,\n        YAMLStringify({\n          packages: [packagePath],\n        })\n      );\n    }\n  }\n}\n","resolvedModuleNames":["/workspace/repo/packages/nx/src/config/configuration.ts","/workspace/repo/packages/nx/src/project-graph/file-utils.ts","/workspace/repo/packages/nx/src/utils/fileutils.ts","/workspace/repo/packages/nx/src/utils/package-json.ts"